/* Relaywise: tokens. See DESIGN.md for the reasoning. */
:root {
  --bg: oklch(0.985 0.005 200);
  --surface: oklch(1 0 0);
  --ink: oklch(0.23 0.035 230);
  --muted: oklch(0.45 0.025 230);
  --rule: oklch(0.9 0.012 230);        /* decorative separators only */
  --edge: oklch(0.58 0.03 230);        /* control edges, 3:1+ on bg */
  --accent: oklch(0.47 0.12 160);      /* signal green: actions + route destinations */
  --accent-press: oklch(0.4 0.11 160);
  --accent-soft: oklch(0.94 0.04 160);
  --beta: oklch(0.92 0.07 85);
  --ring: oklch(0.5 0.16 255);
  --on-dark: oklch(0.97 0.005 200);
  --on-dark-muted: oklch(0.82 0.02 230);

  --display: "Bricolage Grotesque", ui-sans-serif, system-ui, sans-serif;
  --body: "Atkinson Hyperlegible", ui-sans-serif, system-ui, sans-serif;

  /* 1.25 scale on a 1.0625rem base */
  --step--1: 0.875rem;
  --step-0: 1.0625rem;
  --step-1: 1.33rem;
  --step-2: 1.66rem;
  --step-3: clamp(1.9rem, 1.4rem + 2vw, 2.6rem);
  --step-4: clamp(2.3rem, 1.5rem + 3.6vw, 4rem);

  --r-sm: 0.375rem;
  --r-md: 0.75rem;
  --r-lg: 1.25rem;
}

*, *::before, *::after { box-sizing: border-box; }

html { color-scheme: light; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--body);
  font-size: var(--step-0);
  line-height: 1.6;
  caret-color: var(--accent);
}

::selection { background: var(--accent-soft); color: var(--ink); }

h1, h2, h3 {
  font-family: var(--display);
  font-weight: 700;
  text-wrap: balance;
  margin: 0;
}

p { margin: 0; text-wrap: pretty; }
ul { margin: 0; padding: 0; list-style: none; }

a { color: inherit; text-underline-offset: 0.2em; }

:focus-visible {
  outline: 3px solid var(--ring);
  outline-offset: 3px;
  border-radius: var(--r-sm);
}

.wrap {
  width: min(100% - 2.5rem, 72rem);
  margin-inline: auto;
}

.visually-hidden {
  position: absolute;
  width: 1px; height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

.skip {
  position: absolute;
  left: 1rem; top: -4rem;
  z-index: 10;
  padding: 0.75rem 1rem;
  background: var(--ink);
  color: var(--on-dark);
  border-radius: var(--r-sm);
}
.skip:focus { top: 1rem; }

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 2.75rem;
  padding: 0.625rem 1.25rem;
  border: 2px solid var(--accent);
  border-radius: var(--r-sm);
  background: var(--accent);
  color: var(--on-dark);
  font-weight: 700;
  text-decoration: none;
  touch-action: manipulation;
  transition: background-color 180ms cubic-bezier(0.22, 1, 0.36, 1),
              border-color 180ms cubic-bezier(0.22, 1, 0.36, 1),
              transform 90ms ease-out;
}
.btn:active { background: var(--accent-press); border-color: var(--accent-press); transform: translateY(1px); }
.btn--small { min-height: 2.5rem; padding: 0.375rem 0.875rem; font-size: var(--step--1); }
.btn--large { min-height: 3.25rem; padding: 0.875rem 1.75rem; font-size: var(--step-1); }
.btn--ghost { background: transparent; color: var(--ink); border-color: var(--ink); }
.btn--ghost:active { background: var(--accent-soft); border-color: var(--ink); }

@media (hover: hover) {
  .btn:hover { background: var(--accent-press); border-color: var(--accent-press); }
  .btn--ghost:hover { background: var(--accent-soft); border-color: var(--ink); }
}

/* ---------- Header ---------- */
.site-header { border-bottom: 1px solid var(--rule); background: var(--surface); }
.site-header__inner {
  display: flex;
  align-items: center;
  gap: 1rem 1.5rem;
  flex-wrap: wrap;
  padding-block: 0.75rem;
}
.logo {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-family: var(--display);
  font-weight: 700;
  font-size: var(--step-1);
  text-decoration: none;
}
/* ponytail: the logo mark is the route line in miniature, pure CSS */
.logo__mark {
  position: relative;
  width: 1.5rem; height: 0.75rem;
}
.logo__mark::before, .logo__mark::after {
  content: "";
  position: absolute;
  top: 50%;
  border-radius: 50%;
  translate: 0 -50%;
}
.logo__mark::before { left: 0; width: 0.45rem; height: 0.45rem; border: 2px solid var(--ink); }
.logo__mark::after { right: 0; width: 0.6rem; height: 0.6rem; background: var(--accent); }
.logo__mark { background: linear-gradient(var(--ink), var(--ink)) center / 60% 2px no-repeat; }

.site-header nav { margin-left: auto; }
.nav { display: flex; gap: 0.25rem 1.25rem; flex-wrap: wrap; }
.nav a {
  display: inline-block;
  padding-block: 0.5rem;
  text-decoration: none;
  font-weight: 700;
  color: var(--muted);
}
@media (hover: hover) { .nav a:hover { color: var(--ink); text-decoration: underline; } }

/* ---------- Signature: the route line ---------- */
.route {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.375rem 0.625rem;
  min-width: 0;
}
.route__from { min-width: 0; overflow-wrap: anywhere; }
.route__wire {
  position: relative;
  flex: 1 1 1.75rem;
  min-width: 1.75rem;
  max-width: 6rem;
  height: 2px;
  background: currentColor;
  opacity: 0.55;
}
.route__wire::before {            /* origin node */
  content: "";
  position: absolute;
  left: -2px; top: 50%;
  width: 6px; height: 6px;
  border-radius: 50%;
  background: currentColor;
  translate: 0 -50%;
}
.route__wire::after {             /* arrowhead */
  content: "";
  position: absolute;
  right: -1px; top: 50%;
  border: 5px solid transparent;
  border-left: 7px solid currentColor;
  border-right: 0;
  translate: 0 -50%;
}
.route__to {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  padding: 0.125rem 0.625rem 0.125rem 0.5rem;
  border-radius: 999px;
  background: var(--accent-soft);
  color: var(--ink);
  font-weight: 700;
  white-space: nowrap;
}
.route--rule { font-size: var(--step--1); color: var(--muted); }
.route--rule .route__from { color: var(--ink); }

/* ---------- Hero ---------- */
.hero {
  display: grid;
  gap: 3rem;
  padding-block: clamp(3rem, 2rem + 5vw, 6.5rem) clamp(3rem, 2rem + 4vw, 5rem);
  align-items: center;
}
@media (min-width: 60rem) {
  .hero { grid-template-columns: 1.05fr 1fr; gap: 4rem; }
}
.hero h1 {
  font-size: var(--step-4);
  line-height: 1.05;
  letter-spacing: -0.025em;
  max-width: 16ch;
}
.hero__lede {
  margin-top: 1.25rem;
  font-size: var(--step-1);
  line-height: 1.5;
  max-width: 34ch;
  color: var(--muted);
}
.hero__actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.75rem 1.25rem;
  margin-top: 2rem;
}
.hero__note { color: var(--muted); font-size: var(--step--1); }

.board {
  margin: 0;
  background: var(--surface);
  border: 1px solid var(--rule);
  border-radius: var(--r-lg);
  box-shadow: 0 1.25rem 2.5rem -1.5rem oklch(0.23 0.035 230 / 0.35);
  overflow: hidden;
}
.board__head {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.875rem 1.25rem;
  border-bottom: 1px solid var(--rule);
  font-size: var(--step--1);
  font-weight: 700;
  color: var(--muted);
}
.board__live { display: inline-flex; align-items: center; gap: 0.4rem; color: var(--accent); }
.board__live::before {
  content: "";
  width: 0.5rem; height: 0.5rem;
  border-radius: 50%;
  background: currentColor;
}
.route--row {
  padding: 1rem 1.25rem;
  font-size: var(--step--1);
  color: var(--muted);
}
.route--row + .route--row { border-top: 1px solid var(--rule); }
.route--row .route__from { flex: 1 1 12rem; color: var(--ink); font-weight: 700; }
.avatar {
  display: inline-grid;
  place-items: center;
  width: 1.375rem; height: 1.375rem;
  border-radius: 50%;
  background: var(--accent);
  color: var(--on-dark);
  font-size: 0.75rem;
}

/* ---------- Sections ---------- */
.section { padding-block: clamp(3.5rem, 2.5rem + 4vw, 6rem); }
.section__head { max-width: 40rem; margin-bottom: 2.5rem; }
.section__head h2 { font-size: var(--step-3); line-height: 1.12; letter-spacing: -0.02em; }
.section__head p { margin-top: 0.75rem; color: var(--muted); font-size: var(--step-1); line-height: 1.5; }

/* ---------- Features ---------- */
.features {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 19rem), 1fr));
  gap: 1.25rem;
}
.card {
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
  padding: 1.5rem;
  background: var(--surface);
  border: 1px solid var(--rule);
  border-radius: var(--r-md);
}
.card .route--rule {
  padding-bottom: 1rem;
  margin-bottom: 0.375rem;
  border-bottom: 1px dashed var(--rule);
}
.card h3 { font-size: var(--step-1); line-height: 1.25; }
.card > p:not(.route) { color: var(--muted); }
.tags { display: flex; flex-wrap: wrap; gap: 0.375rem; margin-top: 0.25rem; }
.tag {
  padding: 0.125rem 0.625rem;
  border: 1px solid var(--edge);
  border-radius: 999px;
  font-size: 0.8125rem;
  font-weight: 700;
  color: var(--ink);
}
.tag--beta { background: var(--beta); border-color: oklch(0.55 0.1 75); }
.more {
  margin-top: auto;
  padding-top: 0.75rem;
  align-self: flex-start;
  font-weight: 700;
  color: var(--accent);
  text-decoration-thickness: 2px;
}
.more::after { content: " →"; }
@media (hover: hover) { .more:hover { color: var(--accent-press); } }

/* ---------- Pricing ---------- */
.section--pricing { background: var(--surface); border-block: 1px solid var(--rule); }
.tiers {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 18rem), 1fr));
  gap: 1.25rem;
  align-items: stretch;
}
.tier {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  padding: 2rem 1.75rem;
  border: 1px solid var(--rule);
  border-radius: var(--r-md);
  background: var(--bg);
}
.tier h3 {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem 0.75rem;
  font-size: var(--step-2);
}
.price { display: flex; align-items: baseline; gap: 0.5rem; }
.price__num {
  font-family: var(--display);
  font-size: var(--step-3);
  font-weight: 700;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}
.price__per { color: var(--muted); }
.tier__list { display: grid; gap: 0.5rem; margin-bottom: 0.5rem; }
.tier__list li { padding-left: 1.5rem; position: relative; }
.tier__list li::before {
  content: "";
  position: absolute;
  left: 0.125rem; top: 0.55em;
  width: 0.6rem; height: 0.35rem;
  border-left: 2px solid var(--accent);
  border-bottom: 2px solid var(--accent);
  rotate: -45deg;
}
.tier .btn { margin-top: auto; }

.tier--featured {
  background: var(--ink);
  color: var(--on-dark);
  border-color: var(--ink);
  --ring: oklch(0.8 0.12 160);
  line-height: 1.65;
}
.tier--featured .route--rule,
.tier--featured .price__per { color: var(--on-dark-muted); }
.tier--featured .route--rule .route__from { color: var(--on-dark); }
.tier--featured .tier__list li::before { border-color: oklch(0.8 0.12 160); }
.tier--featured .btn { background: oklch(0.8 0.12 160); border-color: oklch(0.8 0.12 160); color: var(--ink); }
@media (hover: hover) {
  .tier--featured .btn:hover { background: oklch(0.88 0.09 160); border-color: oklch(0.88 0.09 160); }
}
.tier--featured .btn:active { background: oklch(0.88 0.09 160); border-color: oklch(0.88 0.09 160); }
.tier__badge {
  padding: 0.125rem 0.625rem;
  border-radius: 999px;
  background: oklch(0.8 0.12 160);
  color: var(--ink);
  font-family: var(--body);
  font-size: 0.8125rem;
  font-weight: 700;
}

/* ---------- Footer ---------- */
.site-footer { padding-block: 3.5rem 2rem; }
.site-footer__inner {
  display: grid;
  gap: 2.5rem;
}
@media (min-width: 52rem) {
  .site-footer__inner { grid-template-columns: 1fr 2fr; }
}
.site-footer__brand p { margin-top: 0.5rem; color: var(--muted); }
.site-footer__links {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(8.5rem, 1fr));
  gap: 1.5rem;
}
.site-footer__links h2 {
  font-family: var(--body);
  font-size: var(--step--1);
  margin-bottom: 0.5rem;
}
.site-footer__links a {
  display: inline-block;
  padding-block: 0.3rem;
  color: var(--muted);
  text-decoration: none;
}
@media (hover: hover) { .site-footer__links a:hover { color: var(--ink); text-decoration: underline; } }
.site-footer__legal {
  grid-column: 1 / -1;
  padding-top: 1.5rem;
  border-top: 1px solid var(--rule);
  color: var(--muted);
  font-size: var(--step--1);
}

/* ---------- Motion preferences ---------- */
@media (prefers-reduced-motion: reduce) {
  .btn { transition-property: background-color, border-color; }
  .btn:active { transform: none; }
}

