/* Relaywise: tokens. See DESIGN.md for the reasoning. */
:root {
  --bg: oklch(0.985 0.005 200);
  --surface: oklch(1 0 0);
  --ink: oklch(0.23 0.035 230);
  --muted: oklch(0.45 0.025 230);
  --rule: oklch(0.9 0.012 230);        /* decorative separators only */
  --edge: oklch(0.58 0.03 230);        /* control edges, 3:1+ on bg */
  --accent: oklch(0.47 0.12 160);      /* signal green: actions + route destinations */
  --accent-press: oklch(0.4 0.11 160);
  --accent-soft: oklch(0.94 0.04 160);
  --beta: oklch(0.92 0.07 85);
  --ring: oklch(0.5 0.16 255);
  --on-dark: oklch(0.97 0.005 200);
  --on-dark-muted: oklch(0.82 0.02 230);

  --display: "Bricolage Grotesque", ui-sans-serif, system-ui, sans-serif;
  --body: "Atkinson Hyperlegible", ui-sans-serif, system-ui, sans-serif;

  /* 1.25 scale on a 1.0625rem base */
  --step--1: 0.875rem;
  --step-0: 1.0625rem;
  --step-1: 1.33rem;
  --step-2: 1.66rem;
  --step-3: clamp(1.9rem, 1.4rem + 2vw, 2.6rem);
  --step-4: clamp(2.3rem, 1.5rem + 3.6vw, 4rem);

  --r-sm: 0.375rem;
  --r-md: 0.75rem;
  --r-lg: 1.25rem;
}

*, *::before, *::after { box-sizing: border-box; }

html { color-scheme: light; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--body);
  font-size: var(--step-0);
  line-height: 1.6;
  caret-color: var(--accent);
}

::selection { background: var(--accent-soft); color: var(--ink); }

h1, h2, h3 {
  font-family: var(--display);
  font-weight: 700;
  text-wrap: balance;
  margin: 0;
}

p { margin: 0; text-wrap: pretty; }
ul { margin: 0; padding: 0; list-style: none; }

a { color: inherit; text-underline-offset: 0.2em; }

:focus-visible {
  outline: 3px solid var(--ring);
  outline-offset: 3px;
  border-radius: var(--r-sm);
}

.wrap {
  width: min(100% - 2.5rem, 72rem);
  margin-inline: auto;
}

.visually-hidden {
  position: absolute;
  width: 1px; height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

.skip {
  position: absolute;
  left: 1rem; top: -4rem;
  z-index: 10;
  padding: 0.75rem 1rem;
  background: var(--ink);
  color: var(--on-dark);
  border-radius: var(--r-sm);
}
.skip:focus { top: 1rem; }

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 2.75rem;
  padding: 0.625rem 1.25rem;
  border: 2px solid var(--accent);
  border-radius: var(--r-sm);
  background: var(--accent);
  color: var(--on-dark);
  font-weight: 700;
  text-decoration: none;
  touch-action: manipulation;
  transition: background-color 180ms cubic-bezier(0.22, 1, 0.36, 1),
              border-color 180ms cubic-bezier(0.22, 1, 0.36, 1),
              transform 90ms ease-out;
}
.btn:active { background: var(--accent-press); border-color: var(--accent-press); transform: translateY(1px); }
.btn--small { min-height: 2.5rem; padding: 0.375rem 0.875rem; font-size: var(--step--1); }
.btn--large { min-height: 3.25rem; padding: 0.875rem 1.75rem; font-size: var(--step-1); }
.btn--ghost { background: transparent; color: var(--ink); border-color: var(--ink); }
.btn--ghost:active { background: var(--accent-soft); border-color: var(--ink); }

@media (hover: hover) {
  .btn:hover { background: var(--accent-press); border-color: var(--accent-press); }
  .btn--ghost:hover { background: var(--accent-soft); border-color: var(--ink); }
